/**
 * Immersive Recitation — shared data-layer types.
 *
 * This feature plays one full-length recitation audio file (the 99 Names of
 * Allah read aloud in order) and shows the matching name on screen, synced to
 * timestamps, against a looping background video.
 *
 * IMPORTANT (licensing) — the actual media referenced by `config/recitationConfig.ts`
 * (the recitation MP3 and the background video clips listed in the playlist) are REAL
 * media assets. They cannot be generated by a coding AI: the project owner must source
 * the recitation audio and any video footage, secure the relevant licenses, and host them
 * under `public/media/...` before the feature can be used. The paths in the config are
 * placeholders pointing at where those files should land.
 */

/** One of the 99 Names with its timing inside the recitation audio. */
export interface AllahName {
  /** Canonical order of the name, zero-padded two-digit string, e.g. "01".."99". */
  id: string;
  /** Arabic script of the name. */
  arabic: string;
  /** Romanised form, e.g. "Ar-Rahman". */
  transliteration: string;
  /** Short English meaning, e.g. "The All-Compassionate". */
  meaning: string;
  /** Seconds from the start of the recitation audio where this name begins. */
  timestampSeconds: number;
  /**
   * RESERVED (Phase 14 extensibility): optional per-word sub-timestamps for
   * word-by-word highlighting. Never emitted by today's data files — purely
   * additive, so existing timestamp JSON stays valid untouched. The name-level
   * `timestampSeconds` remains the single source for the synchronizer; these
   * only add word-level granularity when a recitation ships them.
   */
  wordTimestamps?: WordTimestampEntry[];
}

/**
 * RESERVED (Phase 14): one word's timing inside a name slot. The current
 * placeholder timestamp files do not include these; the schema is simply left
 * open so a future recitation can nest per-word timestamps without any change
 * to the name-level synchronization model.
 */
export interface WordTimestampEntry {
  /** Word index within the name (0-based, reading order). */
  wordIndex: number;
  /** Seconds from the start of the recitation audio where this word begins. */
  timestampSeconds: number;
}

/**
 * A single timing row, as stored one-per-line in `data/namesTimestamps.json`.
 * That file's structure matches this interface exactly; it is the source of the
 * `timestampSeconds` values that get merged onto `AllahName` entries.
 */
export interface TimestampEntry {
  /** Same id convention as `AllahName.id` — "01".."99". */
  id: string;
  /** Seconds from the start of the recitation audio where this name begins. */
  timestampSeconds: number;
}

/**
 * Which recitation audio the immersive feature is currently pointed at.
 * All media URL fields are REQUIRED, non-empty strings — `assertValidRecitationConfig()`
 * (config/recitationConfig.ts) verifies them at app start in development.
 */
export interface ReciterConfig {
  /** Unique id for this recitation/reciter, e.g. "names-of-allah". */
  readonly id: string;
  /** Display name of the reciter or recording (e.g. "Husary"). */
  readonly name: string;
  /** URL of the full-length recitation audio file (absolute path or https/blob/data URL). */
  readonly audioUrl: string;
  /**
   * What kind of timing this track uses:
   * - 'recitation': uniform speech timing only (the per-name concatenation) —
   *   names are spoken back-to-back.
   * - 'nasheed':  melodic rendition — may open/close with instrumental or
   *   harmonized passages and leave musical spacing BETWEEN names, so name
   *   timestamps are NOT evenly paced. Timing draws on `introSeconds` /
   *   `outroSeconds` in addition to the per-name rows.
   *
   * PHASE 1 DECISION (owner) — see LICENSE NOTICE in config/recitationConfig.ts:
   * the melodic full-recitation track is sourced from a developer-facing
   * licensed Islamic audio library. The owner must obtain the audio file AND
   * written confirmation of commercial-use rights BEFORE wiring it in. Until
   * then the concatenated speech track stays active (style 'recitation').
   */
  readonly style: 'nasheed' | 'recitation';
  /**
   * Seconds of instrumental/harmonized intro BEFORE the first name. Speech
   * tracks use 0.
   */
  readonly introSeconds: number;
  /**
   * Seconds of instrumental/harmonized outro AFTER the last name. Speech
   * tracks use 0.
   */
  readonly outroSeconds: number;
  /**
   * Total length of the recitation audio in seconds (measured, not estimated).
   *
   * This exists because the browser CANNOT always estimate the duration of the
   * file: for raw MPEG-1 Layer III CBR streams without a Xing/Info header (e.g.
   * the concatenated `asma-ul-husna-full.mp3`, Phase 3) Chrome reports
   * `audio.duration === Infinity` forever. The engine prefers a FINITE
   * `audio.duration` whenever the browser reports one; this value is the
   * fallback so seeking to the end / the progress bar / the remaining-time
   * display always have a real number to work with.
   *
   * When the audio file is swapped, update this alongside `timestamps` — it is
   * tied to the same file (measure with `afinfo` or a media player).
   */
  readonly durationSeconds: number;
  /**
   * Timing rows for the audio. These live in `data/namesTimestamps.json` and are
   * wired in here so a new reciter requires changing this config only.
   */
  readonly timestamps: readonly TimestampEntry[];
  /**
   * Whether the engine should seamlessly restart the track when it ends
   * (meditation/long-listen mode) instead of pausing. The last name stays on
   * screen during the loop point because the synchronizer holds the final
   * index until the first name's timestamp arrives again. Defaults to false.
   */
  readonly loop?: boolean;
}

/** A looping background video clip shown while the recitation plays. */
export interface BackgroundVideoAsset {
  /** Unique id for this clip. */
  readonly id: string;
  /** Public URL of the video file (absolute path or https URL). */
  readonly url: string;
  /** Public URL of the poster frame displayed before the video buffers/loads. */
  readonly posterUrl: string;
}